#!/usr/bin/env python3
"""Reuse launcher artifacts only when both their inputs and generated bytes still match."""
import hashlib,json,pathlib,subprocess,sys
project=pathlib.Path(__file__).resolve().parents[1];root=project.parents[1];marker=project/'target/prepared-runtime.json'
modules=['ledger-domain','ledger-persistence','ledger-api','ledger-verification']
def fingerprint(files):
 h=hashlib.sha256()
 for file in sorted(set(files)):
  h.update(str(file.relative_to(root)).encode()+b'\0'+file.read_bytes()+b'\0')
 return h.hexdigest()
source=[root/'pom.xml',project/'pom.xml']
for name in modules:
 module=project/name;source.append(module/'pom.xml');source.extend(f for f in (module/'src').rglob('*') if f.is_file())
artifacts=[]
for name in modules:artifacts.extend(f for f in (project/name/'target/classes').rglob('*') if f.is_file())
jar=project/'ledger-api/target/clearledger-api-1.0.0-SNAPSHOT-exec.jar';artifacts.append(jar)
dependencies=list((project/'ledger-verification/target/dependency').glob('*.jar'));artifacts.extend(dependencies)
required=[project/'ledger-domain/target/classes/io/github/cheshmakzanoon/portfolio/clearledger/Money.class',project/'ledger-persistence/target/classes/io/github/cheshmakzanoon/portfolio/clearledger/LedgerStore.class',project/'ledger-verification/target/classes/io/github/cheshmakzanoon/portfolio/clearledger/Workload.class',jar]
if not all(f.is_file() for f in required) or not any(f.name.startswith('postgresql-') for f in dependencies):sys.exit(1)
state={'schemaVersion':1,'sourceSha256':fingerprint(source),'artifactSha256':fingerprint(artifacts),'artifactCount':len(artifacts)}
if sys.argv[1]=='check':
 try:previous=json.loads(marker.read_text())
 except (OSError,ValueError):sys.exit(1)
 sys.exit(0 if previous==state else 1)
elif sys.argv[1]=='write':
 marker.parent.mkdir(parents=True,exist_ok=True);temporary=marker.with_suffix('.tmp');temporary.write_text(json.dumps(state,indent=2)+'\n');temporary.replace(marker)
else:raise SystemExit('usage: runtime-cache.py check|write')
